"use strict";

// esbuild smoke check for the ES module graph (Phase 1, step 6 of
// MODERNIZATION.md).
//
// Bundles src/js/index.js and evaluates the result under node. This is a CHECK
// ARTIFACT, not a shipping one: since step 7a build/js/Cindy.js comes from
// tools/build-cindy.js, which composes a once-evaluated and a per-instance
// bundle. This check keeps the plain, once-evaluated view of the graph honest:
// the entry must bundle, every module must be reachable from it, and the graph
// must initialize without throwing. Both scripts share tools/esbuild-common.js
// so the check and the shipping build cannot resolve the graph differently.
//
// Run: node tools/bundle-esm.js

const fs = require("fs");
const path = require("path");
const esbuild = require("esbuild");

const { repoRoot, srcRoot, tsExtensionResolve, commonOptions, nonGraphSources } = require("./esbuild-common");

const outfile = path.join(repoRoot, "build", "js", "Cindy.esm-check.js");
const globalName = "CindyJSModule";

//////////////////////////////////////////////////////////////////////
// Globals the concat build gets from files that are not modules yet.
//
//   version     - build/js/Version.js, generated by make from the git id.
//                 At the flip this becomes an esbuild `define`; for the check
//                 bundle a fixed string is enough and keeps the output stable.
//   generateId  - src/js/CindyJS.js. In the shipping bundle the once-scope
//                 binds it across the factory boundary; here the counter
//                 semantics (unique ids per page) are reproduced inline.
//
// The remaining non-standard free globals in the core (ClipperLib,
// enableInlineVideo, WebKitMutationObserver - see check-esm-graph.js section e)
// are genuinely external: third-party scripts and a vendor-prefixed DOM API,
// all referenced from function bodies only, so the bundle does not need them
// to initialize.
//
// The banner sits outside the IIFE, in the enclosing (CommonJS) scope, so the
// bundled modules close over it exactly the way they close over Head.js today.
const banner = [
    'var version = "esm-check";',
    "var __cindyIdCounter = 0;",
    'function generateId(prefix) { return (prefix === undefined ? "CindyJSid" : prefix) + ++__cindyIdCounter; }',
].join("\n");

//////////////////////////////////////////////////////////////////////
// Which modules must end up in the bundle

function collectRuntimeModules(dir, out) {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
        const full = path.join(dir, entry.name);
        if (entry.isDirectory()) {
            if (entry.name !== "ifs" && entry.name !== "includes") collectRuntimeModules(full, out);
        } else if (
            /\.(js|ts)$/.test(entry.name) &&
            !/\.d\.ts$/.test(entry.name) &&
            // Entry points, concat scaffolding, the once-evaluated module and
            // the substituted-in browser seam are not part of this graph; see
            // tools/esbuild-common.js for the reasoning per file.
            !nonGraphSources.has(entry.name)
        ) {
            out.push(path.relative(repoRoot, full).replace(/\\/g, "/"));
        }
    }
    return out;
}

//////////////////////////////////////////////////////////////////////

async function main() {
    const result = await esbuild.build({
        ...commonOptions,
        entryPoints: [path.join(srcRoot, "index.js")],
        format: "iife",
        globalName,
        // Makes the namespace reachable from node's require() without turning
        // the output into a CommonJS bundle - the shape stays the one the
        // shipping IIFE will have.
        footer: { js: `if (typeof module !== "undefined") module.exports = ${globalName};` },
        banner: { js: banner },
        sourcemap: false,
        minify: false,
        metafile: true,
        plugins: [tsExtensionResolve],
        outfile,
    });

    const bundled = new Set(Object.keys(result.metafile.inputs));
    const expected = collectRuntimeModules(srcRoot, []).sort();
    const absent = expected.filter((f) => !bundled.has(f));
    if (absent.length) {
        console.error("Modules missing from the bundle (unreachable from src/js/index.js):");
        for (const f of absent) console.error("  " + f);
        process.exit(1);
    }
    console.log(
        `bundled ${bundled.size} modules -> ${path.relative(repoRoot, outfile)} ` +
            `(${(fs.statSync(outfile).size / 1024).toFixed(0)} kB)`
    );

    // Evaluate, with the same shim ref/js/runtests.js uses for the concat
    // bundle. expose.ts provides the window/document stubs internally.
    // Node >= 21.2 defines a read-only global navigator of its own, which the
    // ref tests opt out of via --no-experimental-global-navigator; either
    // variant satisfies the core, so only fill the gap when there is one.
    if (typeof navigator === "undefined") global.navigator = {};
    const ns = require(outfile);
    // esbuild emits a single IIFE with every module body inlined as top-level
    // statements, so require() returning at all means all 35 module bodies ran.
    const api = Object.keys(ns).sort();
    console.log(`evaluated OK; exports: ${api.join(", ")}`);
    // Since step 7a Setup.js takes the API object from the environment seam
    // (expose.ts here, expose.browser.js in the shipping bundle) rather than
    // from `this`, so this is the node stub - an object, not undefined.
    console.log(`  typeof CindyJS: ${typeof ns.CindyJS}`);

    for (const name of ["CindyJS", "createCindy", "default"]) {
        if (!(name in ns)) {
            console.error(`missing export: ${name}`);
            process.exit(1);
        }
    }
    console.log("OK: ESM entry bundles and its module graph initializes under node.");
}

main().catch((err) => {
    console.error(err.message || err);
    process.exit(1);
});
